const businessSchema=z.object({name,type:z.enum(BUSINESS_TYPES as [string,...string[]]).default('SaaS / App'),website:text(2000).default(''),description:text(3000).default(''),brain:brainSchema.optional(),kit:z.object({primary_color:z.string().regex(/^#[0-9a-f]{6}$/i).optional(),accent_color:z.string().regex(/^#[0-9a-f]{6}$/i).optional(),heading_font:text(60).regex(/^[\w -]+$/).optional(),body_font:text(60).regex(/^[\w -]+$/).optional(),logo_asset_id:z.string().nullable().optional()}).passthrough().optional(),preferences:z.object({platform:z.enum(['TikTok','Instagram','Both']).optional(),goal:text(100).optional(),tone:text(100).optional(),template:z.enum(TEMPLATE_NAMES as [string,...string[]]).optional(),cta_type:z.enum(['Integrated','Separate Slide','None']).optional(),formats:z.array(text(30)).max(3).optional()}).optional(),onboarding_step:z.number().int().min(1).max(6).optional(),onboarding_status:z.enum(['in_progress','complete']).optional()});
