const respond=(data:any,status=200,headers:Record<string,string>={})=>Response.json(data,{status,headers:{'Cache-Control':'no-store',...headers}});
async function body(req:Request){if(Number(req.headers.get('content-length')||0)>200000)throw new AppError('This request is too large.',413);try{const source=await req.text();if(source.length>200000)throw new AppError('This request is too large.',413);return JSON.parse(source)}catch{throw new AppError('Invalid request data.')}}
const esc=(s:string)=>s.replaceAll('&','&amp;').replaceAll('<','&lt;').replaceAll('>','&gt;').replaceAll('"','&quot;');
async function emailToken(user:any,purpose:string,origin:string){const token=uid()+uid();await run('INSERT INTO auth_tokens (id,user_id,purpose,expires_at) VALUES (?,?,?,?)',await hash(token),user.id,purpose,new Date(Date.now()+3600000).toISOString());const link=origin+(purpose==='verify'?'/verify-email':'/reset-password')+'?token='+encodeURIComponent(token);await sendEmail(user.email,purpose==='verify'?'Verify your Riffi email':'Reset your Riffi password',`<p>Hi ${esc(user.first_name)},</p><p><a href="${esc(link)}">${purpose==='verify'?'Verify your email':'Reset your password'}</a></p><p>This link expires in one hour.</p>`)}
function admin(user:any){const allowed=String(config().ADMIN_EMAILS||'').split(',').map((s:string)=>s.trim().toLowerCase()).filter(Boolean);if(!user.verified||!allowed.includes(user.email.toLowerCase()))throw new AppError('Administrator access required.',403)}

async function reserveUsage(workspace:any,businessId:string,feature:string){const id=uid();const limit=await entitlement(workspace,feature+'.monthly');const reserved=await run('INSERT INTO usage_records (id,workspace_id,business_id,feature,quantity,created_at) SELECT ?,?,?,?,?,? WHERE (SELECT COALESCE(SUM(quantity),0) FROM usage_records WHERE workspace_id=? AND feature=? AND created_at>=?)<?',id,workspace.id,businessId,feature,1,now(),workspace.id,feature,now().slice(0,7),limit);if(!reserved.meta.changes)throw new AppError('Your monthly '+feature+' allowance has been reached. Visit Billing to change your plan.',402);return id}
