if(action==='signup'&&method==='POST'){const d=signupSchema.parse(await body(req));if(await one('SELECT id FROM users WHERE email=?',d.email))throw new AppError('An account with this email already exists. Sign in instead.',409);const u=await createAccount(d);return respond({user:publicUser(u)},201,{'Set-Cookie':await sessionCookie(req,u.id)})}
if(action==='login'&&method==='POST'){const d=z.object({email,password:z.string().min(1).max(128)}).parse(await body(req));const u=await one('SELECT * FROM users WHERE email=? AND status=?',d.email,'active');if(!u||!u.password_hash||!await passwordMatch(d.password,u.password_hash))throw new AppError('Email or password is incorrect.',401);await audit(u.id,'account.login');return respond({user:publicUser(u)},200,{'Set-Cookie':await sessionCookie(req,u.id)})}
if(action==='logout'&&method==='POST'){const token=(req.headers.get('cookie')||'').match(/cp_session=([^;]+)/)?.[1];if(token)await run('DELETE FROM sessions WHERE id=?',await hash(token));return respond({ok:true},200,{'Set-Cookie':clearCookie(req)})}
