if(action==='forgot-password'&&method==='POST'){if(!availability().email)throw new AppError('Password reset email is not configured yet. Contact the workspace owner.',503);const d=z.object({email}).parse(await body(req));const u=await one('SELECT * FROM users WHERE email=?',d.email);if(u?.password_hash)await emailToken(u,'reset',origin);return respond({message:'If that email has an account, a reset link is on its way.'})}
if(action==='reset-password'&&method==='POST'){const d=z.object({token:text(200).min(20),password:z.string().min(10).max(128)}).parse(await body(req));const token=await one('DELETE FROM auth_tokens WHERE id=? AND purpose=? AND expires_at>? RETURNING *',await hash(d.token),'reset',now());if(!token)throw new AppError('This reset link expired or was already used. Request a new link.');const h=await passwordHash(d.password);await database().batch([stmt('UPDATE users SET password_hash=? WHERE id=?',h,token.user_id),stmt('DELETE FROM sessions WHERE user_id=?',token.user_id),stmt('DELETE FROM auth_tokens WHERE user_id=? AND purpose=?',token.user_id,'reset')]);return respond({message:'Password updated. You can now sign in.'})}
