if(!path[1]&&method==='POST'){const d=businessSchema.parse(await body(req));if(d.website)validatePublicUrl(d.website);const max=await entitlement(workspace,'businesses.max');const id=uid(),date=now();const result=await run('INSERT INTO businesses (id,workspace_id,name,website,type,description,brain,kit,preferences,onboarding_step,onboarding_status,created_at,updated_at) SELECT ?,?,?,?,?,?,?,?,?,1,?,?,? WHERE (SELECT COUNT(*) FROM businesses WHERE workspace_id=?)<?',id,workspace.id,d.name,d.website,d.type,d.description,json(d.brain||{description:d.description}),json({primary_color:'#7047eb',accent_color:'#d9ef9b',heading_font:'Arial',body_font:'Arial',...d.kit}),json(d.preferences||{platform:'Both',goal:'Engagement',tone:'Auto',template:'Editorial',cta_type:'Integrated'}),'in_progress',date,date,workspace.id,max);if(!result.meta.changes)throw new AppError('Your plan’s business limit is reached. Visit Billing to add more businesses.',402);await audit(user.id,'business.created',id);return respond({business:await requireBusiness(user.id,id)},201)}
